import 'package:flutter/material.dart';
import 'api.dart';
import 'work_pages.dart';
const apiBaseUrl=String.fromEnvironment('API_BASE_URL',defaultValue:'http://10.0.2.2:8000');
void main()=>runApp(const WorkPortalApp());
class WorkPortalApp extends StatelessWidget{const WorkPortalApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Рабочий портал',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.blueGrey),home:const AuthPage());}
class AuthPage extends StatefulWidget{const AuthPage({super.key});@override State<AuthPage> createState()=>_AuthPageState();}
class _AuthPageState extends State<AuthPage>{final api=ApiClient(baseUrl:apiBaseUrl);final loginUser=TextEditingController(),loginPass=TextEditingController(),invite=TextEditingController(),regUser=TextEditingController(),regPass=TextEditingController();bool registerMode=false,busy=false;String? error;Future<void> submit()async{setState(()=>busy=true);try{final u=registerMode?await api.register(invite.text.trim(),regUser.text.trim(),regPass.text):await api.login(loginUser.text.trim(),loginPass.text);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomePage(api:api,user:u)));}catch(e){if(mounted)setState(()=>error='$e');}if(mounted)setState(()=>busy=false);}InputDecoration d(String l)=>InputDecoration(labelText:l,border:const OutlineInputBorder());@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Рабочий портал',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:18),SegmentedButton<bool>(segments:const[ButtonSegment(value:false,label:Text('Вход')),ButtonSegment(value:true,label:Text('Регистрация'))],selected:{registerMode},onSelectionChanged:(v)=>setState(()=>registerMode=v.first)),const SizedBox(height:18),if(registerMode)...[TextField(controller:invite,decoration:d('Ключ приглашения')),const SizedBox(height:12),TextField(controller:regUser,decoration:d('Логин')),const SizedBox(height:12),TextField(controller:regPass,obscureText:true,decoration:d('Пароль'))]else...[TextField(controller:loginUser,decoration:d('Логин')),const SizedBox(height:12),TextField(controller:loginPass,obscureText:true,decoration:d('Пароль'))],const SizedBox(height:16),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Подождите…':registerMode?'Создать аккаунт':'Войти'))])))))));}
class HomePage extends StatelessWidget{const HomePage({super.key,required this.api,required this.user});final ApiClient api;final Map<String,dynamic> user;Future<void> logout(BuildContext c)async{await api.logout();if(c.mounted)Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>const AuthPage()),(_)=>false);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Рабочий портал'),actions:[IconButton(onPressed:()=>logout(c),icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${user['username']}'),subtitle:Text('Роль: ${user['role']}'))),Card(child:ListTile(leading:const Icon(Icons.assignment),title:const Text('Рабочие формы'),subtitle:const Text('Заполняйте назначенные рабочие данные'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>FormsPage(api:api))))),Card(child:ListTile(leading:const Icon(Icons.notifications),title:const Text('Уведомления'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>NotificationsPage(api:api))))),Card(child:ListTile(leading:const Icon(Icons.manage_accounts),title:const Text('Настройки аккаунта'),onTap:()=>settings(c))),if(user['role']=='owner')Card(child:ListTile(leading:const Icon(Icons.key),title:const Text('Регистрация сотрудников'),subtitle:const Text('Генерация одноразовых ключей'),onTap:()=>invites(c)))]));void invites(BuildContext c){String role='worker';showModalBottomSheet(context:c,builder:(s)=>Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField(value:role,items:const[DropdownMenuItem(value:'worker',child:Text('Работник')),DropdownMenuItem(value:'manager',child:Text('Руководитель')),DropdownMenuItem(value:'admin',child:Text('Администратор'))],onChanged:(v)=>role=v??'worker'),const SizedBox(height:12),FilledButton(onPressed:()async{final d=await api.createInvite(role);if(s.mounted)showDialog(context:s,builder:(_)=>AlertDialog(title:const Text('Ключ создан'),content:SelectableText('${d['code']}')));},child:const Text('Сгенерировать ключ'))])));}void settings(BuildContext c){final u=TextEditingController(text:'${user['username']}'),p=TextEditingController();showDialog(context:c,builder:(d)=>AlertDialog(title:const Text('Смена логина'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:u,decoration:const InputDecoration(labelText:'Новый логин')),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Текущий пароль'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Отмена')),FilledButton(onPressed:()async{try{await api.changeUsername(u.text.trim(),p.text);if(d.mounted)Navigator.pop(d);}catch(e){if(d.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));}},child:const Text('Сохранить'))]));}}
